/**
 * Sandbox tools for testing Cline SDK tool calling (Layer 1: pure isolation).
 *
 * These mirror the Ghost Cursor vocabulary from `src/shared/types.ts` (`ToolCall`)
 * but are declared with the Cline SDK's `createTool`, so the model-facing contract
 * is generated by the SDK rather than hand-written.
 *
 * Everything in this file is deterministic and offline: no browser, no network,
 * no model. That is what makes it safe to run on every commit.
 */
import { createTool } from '@cline/sdk';
import { z } from 'zod';

/*
 * Input schemas are exported separately from the tools so tests can validate them
 * directly with `safeParse` without going through a model.
 */

export const pointAtInput = z.object({
  element_id: z.string().describe('Element id from the latest page snapshot, e.g. "e12".'),
  hint: z.string().describe('Short label to show next to the ghost cursor.').optional(),
});

export const clickInput = z.object({
  element_id: z.string().describe('Element id from the latest page snapshot, e.g. "e12".'),
});

export const scrollInput = z.object({
  direction: z.enum(['down', 'up', 'top', 'bottom']).describe('Which way to scroll the page.'),
  amount: z
    .number()
    .int()
    .min(1)
    .describe('Optional pixel distance; at most one viewport height.')
    .optional(),
});

export const finishInput = z.object({
  message: z.string().describe('What to tell the user when the task is done.'),
});

export interface RecordedCall {
  tool: string;
  input: unknown;
}

export interface GhostTools {
  tools: ReturnType<typeof createTool>[];
  /** Every execute() that actually ran, in order. Assert against this, not the model's text. */
  calls: RecordedCall[];
}

/**
 * Build the tool set plus a recorder.
 *
 * Note how `description` carries the policy that would otherwise live in a prompt:
 * when to use the tool, when NOT to, and the hard constraint (never touch
 * password/payment fields). Tool-call accuracy is mostly a description problem.
 */
export function createGhostTools(): GhostTools {
  const calls: RecordedCall[] = [];

  const pointAt = createTool({
    name: 'point_at',
    description:
      'Move the ghost cursor to exactly one element on the page and label it. ' +
      'Use this to GUIDE the user without acting. This tool is read-only and never clicks.',
    inputSchema: pointAtInput,
    async execute(input: z.infer<typeof pointAtInput>) {
      calls.push({ tool: 'point_at', input });
      return { ok: true, pointed: input.element_id, hint: input.hint ?? 'Look here' };
    },
  });

  const clickElement = createTool({
    name: 'click',
    description:
      'Click one element on the page by its snapshot id. Only use this when the user ' +
      'explicitly asked for a click. Never click password, payment or personal-data fields.',
    inputSchema: clickInput,
    async execute(input: z.infer<typeof clickInput>) {
      calls.push({ tool: 'click', input });
      return { ok: true, clicked: input.element_id };
    },
  });

  const scrollPage = createTool({
    name: 'scroll',
    description:
      'Scroll the page and return the new offset. Use direction "top" or "bottom" to jump ' +
      'to an end of the document. Scrolls at most one viewport height per call.',
    inputSchema: scrollInput,
    async execute(input: z.infer<typeof scrollInput>) {
      calls.push({ tool: 'scroll', input });
      return { ok: true, direction: input.direction, amount: input.amount ?? 1 };
    },
  });

  const finishTask = createTool({
    name: 'finish',
    description:
      'Finish the task and hand control back to the user with a short message. ' +
      'Call this as soon as the goal is met so the run ends cleanly.',
    inputSchema: finishInput,
    // Marks a completion tool: a successful call ends the agent loop.
    lifecycle: { completesRun: true },
    async execute(input: z.infer<typeof finishInput>) {
      calls.push({ tool: 'finish', input });
      return { ok: true, message: input.message };
    },
  });

  return { tools: [pointAt, clickElement, scrollPage, finishTask], calls };
}
